def _post_json(url: str, headers: dict, payload: dict) -> dict:
    data = json.dumps(payload).encode("utf-8")
    req = urllib.request.Request(url, data=data, headers=headers, method="POST")
    with urllib.request.urlopen(req, timeout=REQUEST_TIMEOUT) as resp:
        return json.loads(resp.read().decode("utf-8"))

def parse_image(images, caption: str = None, mime: str = "image/jpeg"):
    """Разбирает одно или несколько изображений в карточку.
    images — bytes или список bytes. Формат ответа тот же, что у
    parse_message, поэтому дальше всё работает без изменений."""
    key = anthropic_key()
    if not key:
        return None
    if isinstance(images, (bytes, bytearray)):
        images = [images]
    if not images:
        return None

    if not mime or not mime.startswith("image/"):
        mime = "image/jpeg"

    content = []
    for img in images[:5]:          # больше пяти за раз — дорого и без пользы
        content.append({
            "type": "image",
            "source": {
                "type": "base64",
                "media_type": mime,
                "data": base64.b64encode(img).decode("ascii"),
            },
        })

    hvost = IMAGE_PROMPT
    if (caption or "").strip():
        hvost += f"\n\nПодпись владельца к материалам:\n{caption.strip()}"
    content.append({"type": "text", "text": hvost})

    try:
        started = datetime.now()
        result = _post_json(
            "https://api.anthropic.com/v1/messages",
            {
                "Content-Type": "application/json",
                "x-api-key": key,
                "anthropic-version": "2023-06-01",
            },
            {
                "model": MODEL,
                "max_tokens": MAX_TOKENS,
                "system": SYSTEM_PROMPT,
                "messages": [{"role": "user", "content": content}],
            },
        )
        elapsed = (datetime.now() - started).total_seconds()
    except urllib.error.HTTPError as e:
        body = e.read()[:300].decode("utf-8", "ignore")
        logging.error(f"Разбор изображения, Anthropic {e.code}: {body}")
        return None
    except Exception as e:
        logging.error(f"Разбор изображения не удался: {e}")
        return None

    chunks = [b.get("text", "") for b in result.get("content", []) if b.get("type") == "text"]
    parsed = _extract_json("\n".join(chunks))
    if not parsed:
        return None

    usage = result.get("usage") or {}
    parsed["_meta"] = {
        "model": result.get("model") or MODEL,
        "elapsed": round(elapsed, 1),
        "tokens_in": usage.get("input_tokens"),
        "tokens_out": usage.get("output_tokens"),
        "source": "изображение",
    }
    logging.info("Разбор изображения: %.1f с, картинок %d", elapsed, len(images[:5]))

    parsed.setdefault("type", "note")
    parsed.setdefault("fields", {})
    parsed.setdefault("question", None)
    parsed.setdefault("summary", "Данные с изображения")
    return parsed

def flatten(obj, out=None):
    """Разворачивает разбор в один уровень.
    Понимает вид {"поле": {"value": ..., "sure": true}} и пропускает
    всё, в чём ИИ не уверен (sure: false) — догадки в карточку не идут."""
    if out is None:
        out = {}
    if isinstance(obj, dict):
        for k, v in obj.items():
            nk = _norm(k)
            if nk in SKIP:
                continue
            if isinstance(v, dict) and "value" in v:
                if v.get("sure") is False:
                    continue
                val = v.get("value")
                if val not in (None, "", "-", "—") and nk not in out:
                    out[nk] = val
                continue
            if isinstance(v, (dict, list)):
                flatten(v, out)
            elif v not in (None, "", "-", "—"):
                if nk not in out:
                    out[nk] = v
    elif isinstance(obj, list):
        for item in obj:
            flatten(item, out)
    return out

def clean(parsed, extra_text=""):
    """Из разбора оставляем только поля карточки.
    extra_text — исходное сообщение: если разбор что-то потерял, ищем там."""
    flat = flatten(parsed if isinstance(parsed, dict) else {})
    text_all = _all_text(flat)
    if extra_text:
        text_all = text_all + " | " + str(extra_text)
    out = {}
    for field, keys in ALLOWED.items():
        raw = _pick(flat, keys)
        if raw in (None, "", "-", "—"):
            for f2, rx in FALLBACK:
                if f2 != field:
                    continue
                m = rx.search(text_all)
                if m:
                    raw = m.group(1) if m.groups() else m.group(0)
                    break
        if raw in (None, ""):
            continue
        if field == "engine_cc":
            val = _cc(raw)
            if val and not (500 <= val <= 8000):
                val = None
        elif field == "mileage_km":
            val = _km(raw)
            if val and not (0 < val <= 2000000):
                val = None
        elif field == "year":
            val = _year(raw)
            if val and not (1980 <= val <= date.today().year + 1):
                val = None
        elif field == "fuel":
            val = _map(raw, FUEL)
        elif field == "gearbox":
            val = _map(raw, GEARBOX)
        elif field == "drive":
            val = _map(raw, DRIVE)
        elif field == "color":
            val = _map(raw, COLOR)
        elif field == "vin":
            vin = str(raw).upper().replace(" ", "").replace("-", "")
            if len(vin) != 17:
                m = _re.search(r"[A-HJ-NPR-Z0-9]{17}", text_all.upper())
                vin = m.group(0) if m else None
            val = vin
        else:
            val = str(raw).strip()
        if val not in (None, ""):
            out[field] = val
    _log_parsed(parsed, out)
    return out

def render(data, existing=None):
    L = ["<b>Автомобиль</b>"]
    if existing:
        L.append("VIN уже есть в базе: <b>%s</b>" % (existing.get("auto_number") or
                                                     "#%s" % existing["id"]))
        L.append("Дополню эту карточку, новую заводить не буду.")
    L.append("")
    for field in ORDER:
        val = data.get(field)
        if val in (None, ""):
            continue
        if field == "engine_cc":
            val = S.num(val, " см³")
        elif field == "mileage_km":
            val = S.num(val, " км")
        L.append("<b>%s:</b> %s" % (LABELS[field], val))

    return "\n".join(L)

def main_menu(staff) -> InlineKeyboardMarkup:
    role = staff["role"]
    rows = []

    new_count = db.count_inbox([db.ST_NEW, db.ST_ASSIGNED, db.ST_RETURNED])
    review_count = len(db.list_cards("cars", db.ST_ON_REVIEW)) + \
        len(db.list_cards("clients", db.ST_ON_REVIEW))

    if role in (db.ROLE_MANAGER, db.ROLE_ADMIN, db.ROLE_OWNER):
        label = f"📥 Необработанное ({new_count})" if new_count else "📥 Необработанное"
        rows.append([InlineKeyboardButton(label, callback_data="inbox_list")])

    if role in (db.ROLE_ADMIN, db.ROLE_OWNER):
        label = f"🔍 На проверке ({review_count})" if review_count else "🔍 На проверке"
        rows.append([InlineKeyboardButton(label, callback_data="review_list")])

    rows.append([
        InlineKeyboardButton("🚗 Автомобили", callback_data="cards_cars"),
        InlineKeyboardButton("👤 Клиенты", callback_data="cards_clients"),
    ])
    rows.append([InlineKeyboardButton("🔎 Поиск", callback_data="search_start")])

    if role in (db.ROLE_ADMIN, db.ROLE_OWNER):
        rows.append([InlineKeyboardButton("📊 Сводка", callback_data="stats")])
    if is_owner(staff):
        rows.append([InlineKeyboardButton("👥 Сотрудники", callback_data="staff_list")])
    rows.append([InlineKeyboardButton("📋 Журнал действий", callback_data="audit_list")])

    # Стоп-кнопка — только владельцу и администратору
    if role in (db.ROLE_ADMIN, db.ROLE_OWNER) and ai.enabled():
        if ai.is_stopped():
            rows.append([InlineKeyboardButton("▶️ Включить ИИ", callback_data="ai_resume")])
        else:
            rows.append([InlineKeyboardButton("🛑 Остановить ИИ", callback_data="ai_stop")])
    return InlineKeyboardMarkup(rows)

async def run_ai_draft(update, context, inbox_id, kind, text, file_id):
    """Fast schema-closed intake. No card write before owner confirmation."""
    import asyncio
    import time
    import ai_fast_schema as fast

    if not ai.enabled():
        return
    msg = update.message
    if ai.is_stopped():
        await msg.reply_text(
            "🛑 ИИ остановлен. Запись сохранена в «Необработанное» и ждёт ручной обработки."
        )
        return

    fast.install_prompt(ai, ai_filter)
    started = time.monotonic()
    parsed = None
    data = {}
    thinking = None

    async def download_bytes(fid):
        tg_file = await context.bot.get_file(fid)
        return bytes(await tg_file.download_as_bytearray())

    if kind in ("voice", "audio", "video_note") and file_id:
        if not ai.voice_enabled():
            await msg.reply_text("🎤 Голос сохранён, но расшифровка не настроена.")
            return
        thinking = await msg.reply_text("🎤 Распознаю...")
        try:
            audio = await asyncio.wait_for(download_bytes(file_id), timeout=2.5)
            text = await asyncio.wait_for(
                asyncio.to_thread(ai.transcribe, audio),
                timeout=fast.VOICE_TRANSCRIBE_SECONDS,
            )
        except asyncio.TimeoutError:
            text = ""
            logging.warning("AI voice hard timeout inbox=%s", inbox_id)
        except Exception as exc:
            text = ""
            logging.error("Не распознал голос: %s", exc)
        if not text:
            await thinking.edit_text("🎤 Запись сохранена. За 10 секунд поля CRM не распознаны.")
            return
        with db.connect() as connection:
            connection.execute("UPDATE inbox SET text=? WHERE id=?", ("[расшифровка] " + text, inbox_id))

    if kind in ("photo", "document") and file_id:
        mime = "image/jpeg"
        if kind == "document":
            mime = (msg.document.mime_type or "") if msg.document else ""
            if not mime.startswith("image/"):
                await msg.reply_text("📎 Файл сохранён. Для быстрого разбора пришлите изображение.")
                return
        if msg.media_group_id:
            marker = "ai_mg_%s" % msg.media_group_id
            if context.chat_data.get(marker):
                return
            context.chat_data[marker] = True
        thinking = await msg.reply_text("🖼 Распознаю, до 7 секунд...")
        deadline = started + fast.PHOTO_HARD_SECONDS
        try:
            image = await asyncio.wait_for(
                download_bytes(file_id),
                timeout=max(0.1, deadline - time.monotonic()),
            )
            parsed = await asyncio.wait_for(
                asyncio.to_thread(ai.parse_image, image, caption=text, mime=mime),
                timeout=max(0.1, deadline - time.monotonic()),
            )
        except asyncio.TimeoutError:
            parsed = None
            logging.warning("AI photo hard timeout inbox=%s", inbox_id)
        except Exception as exc:
            parsed = None
            logging.error("Не распознал изображение: %s", exc)
        parsed = fast.sanitize_parsed(parsed, ai_filter, db)
        data = fast.clean_car(parsed, ai_filter, text or "")
        if not data:
            await thinking.edit_text(
                "🖼 Изображение сохранено. За 7 секунд поля CRM не найдены. "
                "Пришлите данные текстом или голосом."
            )
            return

    if parsed is None and (text or "").strip():
        if thinking is None:
            thinking = await msg.reply_text("🧠 Распознаю...")
        quick = fast.fast_text_data(text, ai_filter)
        try:
            parsed = await asyncio.wait_for(
                asyncio.to_thread(ai.parse_message, text),
                timeout=fast.TEXT_HARD_SECONDS,
            )
        except asyncio.TimeoutError:
            parsed = None
            logging.warning("AI text hard timeout inbox=%s", inbox_id)
        except Exception as exc:
            parsed = None
            logging.error("Не распознал текст: %s", exc)
        safe = fast.sanitize_parsed(parsed, ai_filter, db)
        if safe and safe.get("type") == "car":
            data = fast.clean_car(safe, ai_filter, text)
        elif quick:
            data = quick
            safe = fast.parsed_from_data(data)
        parsed = safe

    if data:
        parsed = fast.parsed_from_data(data)
        issues = ai.validate(parsed)
        context.user_data["ai_draft"] = {
            "inbox_id": inbox_id,
            "parsed": parsed,
            "clean_data": data,
            "source_text": "",
            "review": None,
        }
        rows = [[InlineKeyboardButton("✅ Разместить", callback_data="ai_ok")], [
            InlineKeyboardButton("✏️ Поправить", callback_data="ai_edit"),
            InlineKeyboardButton("❌ Отменить", callback_data="ai_no"),
        ]]
        elapsed = time.monotonic() - started
        await thinking.edit_text(
            ai_filter.render(data) + "\n\n⏱ %.1f с" % elapsed,
            parse_mode="HTML",
            reply_markup=InlineKeyboardMarkup(rows),
        )
        return

    if parsed and parsed.get("type") == "client":
        safe = fast.sanitize_parsed(parsed, ai_filter, db)
        clean_data = ai.to_card_data(safe) if safe else {}
        context.user_data["ai_draft"] = {
            "inbox_id": inbox_id, "parsed": safe, "clean_data": clean_data,
            "source_text": "", "review": None,
        }
        await thinking.edit_text(
            ai_filter.render_from(safe, ai.validate(safe)),
            parse_mode="HTML",
            reply_markup=InlineKeyboardMarkup([[
                InlineKeyboardButton("✅ Сохранить", callback_data="ai_ok"),
                InlineKeyboardButton("❌ Отменить", callback_data="ai_no"),
            ]]),
        )
        return

    if thinking is None:
        thinking = await msg.reply_text("🧠 Распознаю...")
    await thinking.edit_text(
        "Запись сохранена. Поля действующей формы CRM не найдены — "
        "пришлите данные автомобиля текстом, фотографией или голосом."
    )

async def notify_managers(context, inbox_id, kind, text):
    managers = db.staff_ids_by_role(db.ROLE_MANAGER)
    if not managers:
        # Некому передавать — предупреждаем владельца, чтобы запись не зависла
        for oid in db.staff_ids_by_role(db.ROLE_OWNER):
            try:
                await context.bot.send_message(
                    oid,
                    f"⚠️ Запись #{inbox_id} сохранена, но менеджеров в системе нет. "
                    f"Добавьте менеджера через «👥 Сотрудники».",
                )
            except Exception:
                pass
        return
    preview = (text or f"[{kind}]")[:200]
    for mid in managers:
        try:
            await context.bot.send_message(
                mid,
                f"📥 <b>Новая информация от владельца</b>\n\n"
                f"Запись #{inbox_id}\n{preview}",
                parse_mode="HTML",
                reply_markup=InlineKeyboardMarkup([[
                    InlineKeyboardButton("Открыть", callback_data=f"inbox_open:{inbox_id}")
                ]]),
            )
        except Exception as e:
            logging.warning(f"Не доставлено менеджеру {mid}: {e}")
